export default function DashboardScreen(){
  const {role}=useLocalSearchParams<{role:string}>(); const owner=role==='owner'; const [tab,setTab]=useState<TabKey>('home');
  const navigationTabs=owner?ownerTabs:workerTabs;
  return <SafeAreaView style={s.screen} edges={['top','bottom']}>
    <ScrollView contentContainerStyle={s.content} showsVerticalScrollIndicator={false}>
      {owner?<OwnerScreen tab={tab} setTab={setTab}/>:<WorkerScreen tab={tab}/>}
    </ScrollView>
    <View style={s.tabBar}>{navigationTabs.map(item=>{const Icon=tabIcons[item.icon as keyof typeof tabIcons];const active=tab===item.key;return <Pressable key={item.key} onPress={()=>setTab(item.key)} style={s.tab}><Icon size={19} color={active?colors.primary:'#A1A8A4'} strokeWidth={2}/><Text style={[s.tabLabel,active&&s.tabActive]}>{item.label}</Text></Pressable>})}</View>
    {owner&&tab==='home'&&<Pressable onPress={()=>setTab('jobs')} style={s.fab}><Text style={s.fabText}>＋ 긴급 구인</Text></Pressable>}
  </SafeAreaView>;
}

function WorkerScreen({tab}:{tab:TabKey}){
  if(tab==='jobs') return <JobsScreen/>;
  if(tab==='work') return <ScheduleScreen/>;
  if(tab==='chat') return <ChatScreen/>;
  if(tab==='my') return <MyScreen/>;
  return <WorkerHome/>;
}

function ScreenHeader({eyebrow,title}:{eyebrow:string;title:string}){return <View style={s.header}><View><Text style={s.hello}>{eyebrow}</Text><Text style={s.heading}>{title}</Text></View><View style={s.bell}><Bell size={19} color={colors.ink} strokeWidth={2}/></View></View>}

function WorkerHome(){return <>
  <ScreenHeader eyebrow="김용병님, 안녕하세요" title="오늘 가능한 근무를 찾았어요"/>
  <View style={s.statusCard}><View><Text style={s.statusEyebrow}>다음 확정 근무</Text><Text style={s.statusTitle}>메가MGC커피 강남역점</Text><Text style={s.statusMeta}>오늘 18:00–22:00 · 4시간</Text></View><Pressable style={s.statusButton}><Text style={s.statusButtonText}>출근 준비</Text></Pressable></View>
  <View style={s.sectionHeader}><Text style={s.sectionTitle}>추천 긴급 공고</Text><Text style={s.more}>전체보기</Text></View><WorkerJobs/>
  <Text style={[s.sectionTitle,{marginTop:30}]}>내 경력 현황</Text><Insight number="12" title="인증 근무 12회" copy="평점 4.9 · 노쇼 없이 성실하게 근무했어요"/>
</>}

function JobsScreen(){
  const [mode,setMode]=useState<'map'|'keyword'>('map');
  return <>
    <ScreenHeader eyebrow="내 경력과 가까운 곳부터" title="긴급 공고 찾기"/>
    <View style={s.searchMode}>
      <Pressable onPress={()=>setMode('map')} style={[s.modeButton,mode==='map'&&s.modeActive]}><MapPinned size={15} color={mode==='map'?colors.ink:colors.muted}/><Text style={[s.modeText,mode==='map'&&s.modeTextActive]}>지도 기반</Text></Pressable>
      <Pressable onPress={()=>setMode('keyword')} style={[s.modeButton,mode==='keyword'&&s.modeActive]}><Search size={15} color={mode==='keyword'?colors.ink:colors.muted}/><Text style={[s.modeText,mode==='keyword'&&s.modeTextActive]}>키워드 검색</Text></Pressable>
    </View>
    {mode==='map'?<MapJobs/>:<KeywordJobs/>}
  </>;
}

function KeywordJobs(){
  const [query,setQuery]=useState(''); const [today,setToday]=useState(false); const [matched,setMatched]=useState(false); const [distance,setDistance]=useState(false);
  const results=useMemo(()=>jobs.filter(job=>{const keyword=query.trim().toLowerCase();const searchable=`${job.brand} ${job.store} ${job.area} ${job.address}`.toLowerCase();return (!keyword||searchable.includes(keyword))&&(!today||job.isToday)&&(!matched||job.matched)}).sort((a,b)=>distance?a.distance-b.distance:0),[query,today,matched,distance]);
  return <>
    <View style={s.searchBox}><Search size={20} color={colors.ink}/><TextInput value={query} onChangeText={setQuery} placeholder="지역·커피 브랜드 검색" placeholderTextColor="#959D99" style={s.searchInput} returnKeyType="search"/><Text style={s.searchCount}>{results.length}</Text></View>
    <View style={s.filters}><FilterButton label="오늘" active={today} onPress={()=>setToday(value=>!value)}/><FilterButton label="경력 일치" active={matched} onPress={()=>setMatched(value=>!value)}/><FilterButton label="거리순" active={distance} onPress={()=>setDistance(value=>!value)}/></View>
    <View style={s.resultHeader}><Text style={s.sectionTitle}>지금 지원 가능</Text><Text style={s.resultCount}>{results.length}개 공고</Text></View>
    {results.length?<JobList data={results}/>:<View style={s.empty}><Search size={28} color="#B3B9B6"/><Text style={s.emptyTitle}>조건에 맞는 공고가 없어요</Text><Text style={s.emptyCopy}>검색어나 필터를 변경해 보세요.</Text></View>}
  </>;
}

function MapJobs(){const [today,setToday]=useState(false);const [matched,setMatched]=useState(false);const available=jobs.filter(job=>(!today||job.isToday)&&(!matched||job.matched));const selected=available[0];return <>
  <View style={s.mapFilters}><FilterButton label="오늘" active={today} onPress={()=>setToday(value=>!value)}/><FilterButton label="경력 일치" active={matched} onPress={()=>setMatched(value=>!value)}/><View style={{flex:1}}/><Pressable style={s.locationButton}><Crosshair size={13} color={colors.ink}/><Text style={s.locationText}>현 위치</Text></Pressable></View>
  <View style={s.map}>
    <View style={[s.road,{top:70,left:-30,width:440,transform:[{rotate:'-8deg'}]}]}/><View style={[s.road,{top:190,left:-35,width:440,transform:[{rotate:'11deg'}]}]}/><View style={[s.roadVertical,{top:-20,left:185,height:390,transform:[{rotate:'6deg'}]}]}/>
    <View style={[s.block,{top:24,left:28,width:100,height:72}]}/><View style={[s.block,{top:105,left:250,width:94,height:82}]}/><View style={[s.block,{top:225,left:30,width:120,height:76}]}/><View style={[s.block,{top:250,left:245,width:105,height:70}]}/>
    <Text style={[s.mapLabel,{top:41,left:44}]}>논현동</Text><Text style={[s.mapLabel,{top:274,left:264}]}>역삼동</Text>
    <View style={[s.pin,{top:95,left:80}]}><Text style={s.pinText}>{Math.min(available.length,2)}</Text></View><View style={[s.pin,{top:135,left:270}]}><Text style={s.pinText}>1</Text></View><View style={[s.pin,s.pinSelected,{top:205,left:173}]}><Text style={s.pinText}>{Math.min(available.length,9)}</Text></View><View style={[s.pin,{top:265,left:315}]}><Text style={s.pinText}>1</Text></View>
    <View style={s.myLocation}><View style={s.myLocationDot}/></View>
  </View>
  {selected&&<View style={s.mapSummary}><View style={s.mapSummaryTop}><Text style={s.mapSummaryLabel}>선택한 지역의 공고</Text><Text style={s.resultCount}>반경 4km · {available.length}개</Text></View><Pressable onPress={()=>openJob(selected.id)} style={s.mapJob}><View style={s.brandLogo}><Text style={s.brandLogoText}>{selected.brand.slice(0,1)}</Text></View><View style={{flex:1}}><Text style={s.jobTitle}>{selected.brand} {selected.store}</Text><Text style={s.jobTime}>{selected.dateLabel} {selected.time} · {selected.distance}km</Text><Text style={s.pay}>{formatPay(selected.hourlyPay)}</Text></View><ChevronRight size={24} color="#AAB0AD"/></Pressable></View>}
</>}

function ScheduleScreen(){
  const [calendarOpen,setCalendarOpen]=useState(false);const [selected,setSelected]=useState({year:2026,month:11,day:18});const [draft,setDraft]=useState(selected);const [viewYear,setViewYear]=useState(2026);const [viewMonth,setViewMonth]=useState(11);
  const selectedDate=new Date(selected.year,selected.month-1,selected.day);const monday=new Date(selectedDate);monday.setDate(selected.day-((selectedDate.getDay()+6)%7));const week=['월','화','수','목','금','토','일'].map((label,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+index);const year=date.getFullYear();const month=date.getMonth()+1;const day=date.getDate();return {label,year,month,day,key:`${year}-${month}-${day}`}});
  const selectedKey=`${selected.year}-${selected.month}-${selected.day}`;const records=SHIFT_RECORDS[selectedKey]??[];
  const openCalendar=()=>{setDraft(selected);setViewYear(selected.year);setViewMonth(selected.month);setCalendarOpen(true)};
  return <>
  <ScreenHeader eyebrow={`${selected.year}년 ${selected.month}월`} title="근무일정"/>
  <View style={s.scheduleCalendarCard}><Pressable onPress={openCalendar} style={s.calendarOpenButton}><View style={s.calendarOpenIcon}><CalendarDays size={18} color={colors.primary}/></View><View style={{flex:1}}><Text style={s.calendarOpenTitle}>캘린더 전체보기</Text></View><ChevronRight size={20} color="#AAB0AD"/></Pressable><View style={s.calendarCardDivider}/><View style={s.weekRow}>{week.map(d=>{const active=d.key===selectedKey;const work=WORK_DAYS.has(d.key);const done=DONE_DAYS.has(d.key);return <Pressable onPress={()=>setSelected({year:d.year,month:d.month,day:d.day})} key={d.key} style={[s.day,active&&s.dayActive]}><Text style={[s.dayName,active&&s.dayTextActive]}>{d.label}</Text><Text style={[s.dayNumber,active&&s.dayTextActive]}>{d.day}</Text>{work||done?<View style={[s.scheduleDot,done&&s.doneDot,active&&s.activeDot]}/>:<View style={s.dotSpacer}/>}</Pressable>})}</View></View>
  <Text style={[s.sectionTitle,{marginTop:28}]}>{selected.month}월 {selected.day}일 근무기록{records.length>1?` · ${records.length}건`:''}</Text>
  {records.length?<View style={s.recordList}>{records.map(record=><View key={`${record.brand}-${record.store}-${record.time}`} style={s.selectedRecord}><View style={s.recordTop}><View style={[s.recordStatus,record.status==='완료'&&s.recordStatusDone]}><Text style={[s.recordStatusText,record.status==='완료'&&s.recordStatusDoneText]}>{record.status}</Text></View><Text style={s.recordTime}>{record.time}</Text></View><Text style={s.recordStore}>{record.brand} {record.store}</Text><Text style={s.recordRole}>{record.role}</Text><View style={s.recordPayRow}><Text style={s.recordPayLabel}>{record.status==='완료'?'받은 시급':'예정 시급'}</Text><Text style={s.recordPay}>{record.wage}</Text></View></View>)}</View>:<View style={s.noRecord}><CalendarDays size={24} color="#B5BCB8"/><Text style={s.noRecordTitle}>근무 기록이 없어요</Text><Text style={s.noRecordCopy}>다른 날짜를 선택해 확인해 보세요.</Text></View>}
  <CalendarModal visible={calendarOpen} year={viewYear} month={viewMonth} selected={draft} onClose={()=>setCalendarOpen(false)} onConfirm={()=>{setSelected(draft);setCalendarOpen(false)}} onYearChange={setViewYear} onMonthChange={(month)=>{if(month<1){setViewYear(y=>y-1);setViewMonth(12)}else if(month>12){setViewYear(y=>y+1);setViewMonth(1)}else setViewMonth(month)}} onSelect={(day)=>setDraft({year:viewYear,month:viewMonth,day})}/>
</>}

function CalendarModal({visible,year,month,selected,onClose,onConfirm,onYearChange,onMonthChange,onSelect}:{visible:boolean;year:number;month:number;selected:{year:number;month:number;day:number};onClose:()=>void;onConfirm:()=>void;onYearChange:(year:number)=>void;onMonthChange:(month:number)=>void;onSelect:(day:number)=>void}){
  const firstDay=new Date(year,month-1,1).getDay();const daysInMonth=new Date(year,month,0).getDate();const cells=[...Array(firstDay).fill(null),...Array.from({length:daysInMonth},(_,i)=>i+1)];while(cells.length%7)cells.push(null);
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}><View style={s.modalBackdrop}><View style={s.calendarSheet}>
    <View style={s.calendarTop}><View><Text style={s.calendarEyebrow}>날짜 선택</Text><Text style={s.calendarSelected}>{selected.year}.{String(selected.month).padStart(2,'0')}.{String(selected.day).padStart(2,'0')}</Text></View><Pressable onPress={onClose} style={s.closeButton}><X size={20} color={colors.ink}/></Pressable></View>
    <View style={s.dateSelectors}><View style={s.dateSelector}><Pressable onPress={()=>onYearChange(year-1)} style={s.selectorButton}><ChevronLeft size={18} color={colors.muted}/></Pressable><Text style={s.selectorValue}>{year}년</Text><Pressable onPress={()=>onYearChange(year+1)} style={s.selectorButton}><ChevronRight size={18} color={colors.muted}/></Pressable></View><View style={s.dateSelector}><Pressable onPress={()=>onMonthChange(month-1)} style={s.selectorButton}><ChevronLeft size={18} color={colors.muted}/></Pressable><Text style={s.selectorValue}>{month}월</Text><Pressable onPress={()=>onMonthChange(month+1)} style={s.selectorButton}><ChevronRight size={18} color={colors.muted}/></Pressable></View></View>
    <View style={s.calendarWeek}>{['일','월','화','수','목','금','토'].map((day,i)=><Text key={day} style={[s.calendarWeekText,i===0&&s.sunday]}>{day}</Text>)}</View>
    <View style={s.calendarGrid}>{cells.map((day,index)=>{if(!day)return <View key={`blank-${index}`} style={s.calendarCell}/>;const key=`${year}-${month}-${day}`;const active=selected.year===year&&selected.month===month&&selected.day===day;const today=key===TODAY_KEY;const work=WORK_DAYS.has(key);const done=DONE_DAYS.has(key);return <Pressable key={key} onPress={()=>onSelect(day)} style={[s.calendarCell,today&&s.calendarToday,active&&s.calendarCellActive]}><Text style={[s.calendarDay,today&&s.calendarTodayText,active&&s.calendarDayActive]}>{day}</Text><View style={s.calendarDots}>{work?<View style={s.scheduleDot}/>:null}{done?<View style={[s.scheduleDot,s.doneDot]}/>:null}</View></Pressable>})}</View>
    <View style={s.legend}><View style={s.legendItem}><View style={s.todayLegend}/><Text style={s.legendText}>오늘</Text></View><View style={s.legendItem}><View style={s.scheduleDot}/><Text style={s.legendText}>예정 근무</Text></View><View style={s.legendItem}><View style={[s.scheduleDot,s.doneDot]}/><Text style={s.legendText}>완료 근무</Text></View></View>
    <Pressable onPress={onConfirm} style={s.calendarConfirm}><Text style={s.calendarConfirmText}>선택 완료</Text></Pressable>
  </View></View></Modal>;
}

